package durations

import (
	"fmt"
	"strconv"
	"strings"
)

const (
	hasFormat = false
	hasCalc   = false
	digitsMax = 5
)

type unit struct {
	name byte
	size int64
}

var units = []unit{{'p', 1}, {'l', 20}, {'r', 400}}

func sizeOf(c byte) (int64, bool) {
	for _, u := range units {
		if u.name == c {
			return u.size, true
		}
	}
	return 0, false
}

func isDig(c byte) bool { return c >= '0' && c <= '9' }

func parse(text string) (int64, string) {
	if text == "" {
		return 0, "error: empty"
	}
	i := 0
	var total, prev int64
	for i < len(text) {
		j := i
		for j < len(text) && isDig(text[j]) {
			j++
		}
		if j == i || j-i > digitsMax {
			return 0, "error: number"
		}
		if j >= len(text) {
			return 0, "error: unit"
		}
		s, ok := sizeOf(text[j])
		if !ok {
			return 0, "error: unit"
		}
		if prev != 0 && s >= prev {
			if s == prev {
				return 0, "error: repeat"
			}
			return 0, "error: order"
		}
		n, _ := strconv.ParseInt(text[i:j], 10, 64)
		total += n * s
		prev = s
		i = j + 1
	}
	return total, ""
}

func format(n int64) string {
	if n == 0 {
		return "0" + string(units[0].name)
	}
	var sb strings.Builder
	for k := len(units) - 1; k >= 0; k-- {
		u := units[k]
		if n >= u.size {
			sb.WriteString(fmt.Sprintf("%d%c", n/u.size, u.name))
			n %= u.size
		}
	}
	return sb.String()
}

// Dur parses, formats or evaluates durations.
func Dur(op, text string) string {
	switch {
	case op == "parse":
		v, e := parse(text)
		if e != "" {
			return e
		}
		return strconv.FormatInt(v, 10)
	case hasFormat && op == "format":
		ok := len(text) >= 1 && len(text) <= 15 && (text == "0" || text[0] != '0')
		for i := 0; i < len(text); i++ {
			if !isDig(text[i]) {
				ok = false
			}
		}
		if !ok {
			return "error: number"
		}
		n, _ := strconv.ParseInt(text, 10, 64)
		return format(n)
	case hasCalc && op == "calc":
		var parts []string
		var ops []byte
		cur := ""
		for i := 0; i < len(text); i++ {
			if text[i] == '+' || text[i] == '-' {
				parts = append(parts, cur)
				ops = append(ops, text[i])
				cur = ""
			} else {
				cur += string(text[i])
			}
		}
		parts = append(parts, cur)
		var total int64
		for k, part := range parts {
			v, e := parse(strings.Trim(part, " "))
			if e != "" {
				return e
			}
			if k == 0 || ops[k-1] == '+' {
				total += v
			} else {
				total -= v
			}
		}
		if total < 0 {
			return "error: negative"
		}
		return format(total)
	}
	return "error: op"
}

