UNITS = [("a", 1), ("b", 6), ("c", 36), ("e", 432), ("f", 2592)]
HAS_FORMAT = False
HAS_CALC = False
DIGITS = 4
DG = "0123456789"


def size_of(c):
    for u, s in UNITS:
        if u == c:
            return s
    return None


def parse(text):
    """(value, None) or (None, error text)"""
    if text == "":
        return None, "error: empty"
    i = 0
    total = 0
    prev = None
    while i < len(text):
        j = i
        while j < len(text) and text[j] in DG:
            j += 1
        if j == i or j - i > DIGITS:
            return None, "error: number"
        if j >= len(text):
            return None, "error: unit"
        s = size_of(text[j])
        if s is None:
            return None, "error: unit"
        if prev is not None and s >= prev:
            return None, "error: repeat" if s == prev else "error: order"
        total += int(text[i:j]) * s
        prev = s
        i = j + 1
    return total, None


def fmt(n):
    if n == 0:
        return "0" + UNITS[0][0]
    out = ""
    for u, s in reversed(UNITS):
        if n >= s:
            out += "%d%s" % (n // s, u)
            n %= s
    return out


def dur(op, text):
    if op == "parse":
        v, e = parse(text)
        return e if e else str(v)
    if HAS_FORMAT and op == "format":
        if not (1 <= len(text) <= 15 and all(c in DG for c in text) and (text == "0" or text[0] != "0")):
            return "error: number"
        return fmt(int(text))
    if HAS_CALC and op == "calc":
        total = 0
        parts = []
        cur = ""
        ops = []
        for c in text:
            if c in "+-":
                parts.append(cur)
                ops.append(c)
                cur = ""
            else:
                cur += c
        parts.append(cur)
        for k, part in enumerate(parts):
            t = part.strip(" ")
            v, e = parse(t)
            if e:
                return e
            total += v if k == 0 or ops[k - 1] == "+" else -v
        if total < 0:
            return "error: negative"
        return fmt(total)
    return "error: op"

