#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "durations.h"

static int failed = 0;

static void check(int i, char *got, const char *want) {
    if (!got || strcmp(got, want) != 0) {
        failed++;
        printf("case %d FAILED\n  got:  [%s]\n  want: [%s]\n", i, got ? got : "(null)", want);
    }
    free(got);
}

int main(void) {
    check(0, dur("parse", "0f608e40b39a"), "262935");
    check(1, dur("parse", "10f15e885c12b"), "64332");
    check(2, dur("format", "2821"), "1f6c2b1a");
    if (failed) {
        printf("%d case(s) failed\n", failed);
        return 1;
    }
    printf("all cases passed\n");
    return 0;
}
